INSERT INTO rituals (slug, title, summary, purpose, visibility, status, engagement, span_weeks, default_cadence, duration_min, prep_lead_days, load, participants, size_min, size_max, format, timing_hint, min_gap_weeks, pairs_well_with, avoid_near, depends_on, facilitator_role, prep_notes, agenda, outputs, materials, anti_patterns, variations, tags, source_name, source_url, attribution, source_verified, category_id) VALUES ('post-launch-retro', 'Post-Launch Retro', 'A retro specifically about how a launch went.', 'Capture launch-specific lessons while they''re still fresh.', 'public', 'published', 'session', NULL, 'adhoc', 45, 1, 'medium', 'cross-functional', 3, 12, 'sync', NULL, NULL, '[]', '[]', 'a completed launch', 'Team member (rotating)', NULL, '[{"title":"What went well / what didn''t, launch-specific","minutes":30},{"title":"What to change next time","minutes":15}]', '["Launch-specific lessons captured before they''re forgotten"]', '[]', '["Skipped when the launch goes smoothly"]', '[]', '["reflection","launch"]', NULL, NULL, NULL, 0, (SELECT id FROM categories WHERE slug = 'reflection-renewal'));
INSERT INTO rituals (slug, title, summary, purpose, visibility, status, engagement, span_weeks, default_cadence, duration_min, prep_lead_days, load, participants, size_min, size_max, format, timing_hint, min_gap_weeks, pairs_well_with, avoid_near, depends_on, facilitator_role, prep_notes, agenda, outputs, materials, anti_patterns, variations, tags, source_name, source_url, attribution, source_verified, category_id) VALUES ('working-agreement-refresh', 'Working Agreement Refresh', 'Revisit and update the team''s explicit working agreements.', 'Keep team norms matched to how the team actually works now.', 'public', 'published', 'recurring', NULL, 'quarterly', 45, 3, 'light', 'core-team', 3, 12, 'sync', NULL, NULL, '[]', '[]', NULL, 'Team member (rotating)', NULL, '[{"title":"Review current agreements","minutes":20},{"title":"Propose changes","minutes":25}]', '["An updated working agreement"]', '[]', '["Written once and never revisited as the team changes"]', '[]', '["reflection","operations"]', NULL, NULL, NULL, 0, (SELECT id FROM categories WHERE slug = 'reflection-renewal'));
INSERT INTO rituals (slug, title, summary, purpose, visibility, status, engagement, span_weeks, default_cadence, duration_min, prep_lead_days, load, participants, size_min, size_max, format, timing_hint, min_gap_weeks, pairs_well_with, avoid_near, depends_on, facilitator_role, prep_notes, agenda, outputs, materials, anti_patterns, variations, tags, source_name, source_url, attribution, source_verified, category_id) VALUES ('team-offsite', 'Team Offsite', 'A day or more away from the daily routine, together.', 'Create space for the deeper conversations daily work crowds out.', 'public', 'published', 'session', NULL, 'annual', 480, 21, 'heavy', 'core-team', 3, 12, 'sync', NULL, NULL, '[]', '[]', NULL, 'Team member (rotating)', NULL, '[{"title":"Strategy/vision discussion"},{"title":"Team-building activity"},{"title":"Social time"}]', '["Renewed alignment and relationships"]', '[]', '["Agenda so packed there''s no unstructured time"]', '[]', '["reflection","culture"]', NULL, NULL, NULL, 0, (SELECT id FROM categories WHERE slug = 'reflection-renewal'));
