INSERT INTO rituals (slug, title, summary, purpose, visibility, status, engagement, span_weeks, default_cadence, duration_min, prep_lead_days, load, participants, size_min, size_max, format, timing_hint, min_gap_weeks, pairs_well_with, avoid_near, depends_on, facilitator_role, prep_notes, agenda, outputs, materials, anti_patterns, variations, tags, source_name, source_url, attribution, source_verified, category_id) VALUES ('quarterly-ritual-audit', 'Quarterly Ritual Audit', 'Step back and assess whether the team''s rituals are actually working.', 'Catch rituals that have gone stale before they quietly die or calcify.', 'public', 'published', 'recurring', NULL, 'quarterly', 60, 5, 'medium', 'core-team', 3, 12, 'sync', NULL, NULL, '["working-agreement-refresh"]', '[]', NULL, 'Team member (rotating)', NULL, '[{"title":"Score the team''s process health across key pillars","minutes":30},{"title":"Decide what to add, cut, or change","minutes":30}]', '["A concrete list of ritual changes for next quarter"]', '[]', '["Findings aren''t fed back into the actual schedule"]', '[]', '["reflection","meta"]', NULL, NULL, NULL, 0, (SELECT id FROM categories WHERE slug = 'reflection-renewal'));
